import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testSortsAlphabetically() {
        Assert.assertEquals("Alice, Bob, Carlos", buildRoster(listOf("Carlos", "Alice", "Bob")))
    }

    @Test
    fun testSingleName() {
        Assert.assertEquals("Alice", buildRoster(listOf("Alice")))
    }

    @Test
    fun testAlreadySorted() {
        Assert.assertEquals("Alpha, Beta, Gamma", buildRoster(listOf("Alpha", "Beta", "Gamma")))
    }
}
